    if (this.renderOrigin === null) this.renderOrigin = tMs;
    // Insertion sort by tMs (the buffer is small enough that O(n)
    // is fine).
    let inserted = false;
    for (let i = 0; i < this.ring.length; i++) {
      if (this.ring[i]!.tMs > tMs) {
        this.ring.splice(i, 0, { tMs, state });
        inserted = true;
        break;
